for k,v in res.items(): rows.append([k,f"{v['sum_Mbps']:.1f}",f"{v['jain_longterm']:.3f}",f"{v['jain_inst']:.3f}",f"{v['min_user_Mbps']:.2f}",pc(v["all_ge_rmin"]),f"{v['users_below_rmin']:.2f}"]+[f"{x:.1f}" for x in v["per_user"]])
